// Supplied clips provide the human motion. This template does not generate it.
const clipMedia=new Map(),clipPortraits=new Map();let endVideoMedia=null,activeClipId=null,framedRecordingReady=false;
function fClamp(v,a,b,fallback=a){v=Number(v);return Number.isFinite(v)?Math.max(a,Math.min(b,v)):fallback}
function clipLength(c){return fClamp(c.length,.1,60,7)}
function framedEndStart(){return state.clips?.length?state.clips.reduce((sum,c)=>sum+clipLength(c),0):21}
function framedDuration(){return framedEndStart()+4}
function framedCuts(){let t=0,cuts=[0];for(const c of state.clips||[]){t+=clipLength(c);cuts.push(t)}return cuts.length>1?cuts:[0,7,14,21]}
function framedSceneLabels(){return [...(state.clips?.length?state.clips.map((c,i)=>'Scene '+(i+1)+' · '+clipLength(c)+'s'):['Clip 1','Clip 2','Clip 3']),'End card · 4s']}
function framedSceneAt(t){let start=0;for(const c of state.clips||[]){const end=start+clipLength(c);if(t<end)return {clip:c,start,local:Math.max(0,t-start)};start=end}return null}
function clipId(){return 'clip-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}
function releaseMedia(record){if(!record)return;record.video.pause();record.video.removeAttribute('src');record.video.load();URL.revokeObjectURL(record.url)}
async function readClip(file){
 if(file.size>150*1024*1024)throw Error('Use a video under 150 MB.');const video=document.createElement('video'),url=URL.createObjectURL(file);video.muted=true;video.playsInline=true;video.preload='auto';
 try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Video took too long to open. Try an H.264 MP4.')),15000);video.onloadeddata=()=>{clearTimeout(timer);resolve()};video.onerror=()=>{clearTimeout(timer);reject(Error('This browser cannot decode '+file.name+'. Try H.264 MP4.'))};video.src=url;video.load()});if(!Number.isFinite(video.duration)||video.duration<=0)throw Error('The video duration could not be read.');return {video,url,file,name:file.name,duration:video.duration};}catch(e){video.pause();URL.revokeObjectURL(url);throw e}
}
async function seekClip(record,to){const v=record.video,target=Math.max(0,Math.min(to,v.duration-.03));v.pause();if(Math.abs(v.currentTime-target)<.025&&v.readyState>=2)return;await new Promise((resolve,reject)=>{let timer=setTimeout(()=>{cleanup();reject(Error('Video seeking timed out: '+record.name))},10000);function cleanup(){clearTimeout(timer);v.removeEventListener('seeked',ready);v.removeEventListener('error',failed)}function ready(){cleanup();resolve()}function failed(){cleanup();reject(Error('Video seek failed: '+record.name))}v.addEventListener('seeked',ready);v.addEventListener('error',failed);v.currentTime=target})}
function stopFramedPlayback(){for(const item of clipMedia.values())item.video.pause();endVideoMedia?.video.pause();activeClipId=null}
async function prepareFramedPlayback(){framedRecordingReady=false;stopFramedPlayback();for(const c of state.clips||[]){const rec=clipMedia.get(c.id);if(rec)await seekClip(rec,fClamp(c.offset,0,rec.duration-.03))}if(endVideoMedia)await seekClip(endVideoMedia,0)}
function validateFramedAssets(){if(!state.clips?.length)return 'Add at least one result video clip in step 3.';for(const c of state.clips){const rec=clipMedia.get(c.id);if(!rec)return 'Reattach video clip: '+c.name;if(Number(c.offset)>=rec.duration)return 'Trim start exceeds clip duration: '+c.name;if(Number(c.offset)+clipLength(c)>rec.duration+.05)return 'Scene duration exceeds available footage: '+c.name}if(state.endVideo&&!endVideoMedia)return 'Reattach the end-card video or remove it in step 7.';return ''}
function syncMedia(rec,target,id,t){
 if(activeClipId!==id){stopFramedPlayback();activeClipId=id}
 const v=rec.video,position=Math.max(0,Math.min(target,rec.duration-.03));
 if(playing||(exporting&&framedRecordingReady)){if(Math.abs(v.currentTime-position)>.22&&!v.seeking)v.currentTime=position;if(v.paused&&position<rec.duration-.06)v.play().catch(()=>{if(!exporting)message('Press Play to allow video playback.')})}
 else{v.pause();if(Math.abs(v.currentTime-position)>.035&&!v.seeking){v.currentTime=position;v.onseeked=()=>{if(!playing&&!exporting)render(time)}}}
 return v;
}
function beginFramedPlayback(){framedRecordingReady=true}
function drawUploadedEndVideo(w,h){if(!state.endVideo||!endVideoMedia||state.template==='framed')return false;const start=duration()*effectEnd(),age=Math.max(0,motionClock-start);const v=syncMedia(endVideoMedia,age,'end',motionClock);drawVideoFrame(v,0,0,w,h,'cover');return true}
function drawVideoFrame(v,x,y,w,h,fit='cover'){if(v.readyState<2)return;const scale=fit==='contain'?Math.min(w/v.videoWidth,h/v.videoHeight):Math.max(w/v.videoWidth,h/v.videoHeight),dw=v.videoWidth*scale,dh=v.videoHeight*scale;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.drawImage(v,x+(w-dw)/2,y+(h-dh)/2,dw,dh);ctx.restore()}
function circlePortrait(im,x,y,r){ctx.save();ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.clip();if(im){const scale=Math.max(r*2/im.width,r*2/im.height),w=im.width*scale,h=im.height*scale;typeof drawCroppedImage==='function'?drawCroppedImage(ctx,im,x-r,y-r,r*2,r*2,1,'cover'):ctx.drawImage(im,x-w/2,y-h/2,w,h)}else{ctx.fillStyle='#aab4c9';ctx.fillRect(x-r,y-r,r*2,r*2);ctx.fillStyle='#e8edf5';ctx.beginPath();ctx.arc(x,y-r*.2,r*.32,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(x,y+r*.62,r*.65,r*.55,0,0,Math.PI*2);ctx.fill()}ctx.restore();ctx.strokeStyle=$('frameColor').value;ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.stroke()}
function renderFramed(t,w,h){
 const landscape=w>h,square=w===h,endStart=framedEndStart(),inEnd=t>=endStart;
 ctx.globalAlpha=1;const gradient=ctx.createLinearGradient(0,0,0,h);gradient.addColorStop(0,inEnd?'#03152d':$('frameGradientTop').value);gradient.addColorStop(1,inEnd?'#102e55':$('frameGradientBottom').value);ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);
  if(inEnd){const age=t-endStart;motionAge=age;if(state.endVideo&&endVideoMedia){const v=syncMedia(endVideoMedia,age,'end',t);drawVideoFrame(v,0,0,w,h,'cover');return}stopFramedPlayback();return}
 const scene=framedSceneAt(t),clip=scene?.clip,local=scene?.local??t%7,rec=clip?clipMedia.get(clip.id):null;motionAge=local;
 const frameW=landscape?w*.50:square?w*.56:w*.80,frameH=landscape?h*.68:square?h*.65:h*.66,fx=landscape?w*.08:(w-frameW)/2,fy=landscape?h*.16:square?h*.17:h*.17;
 text(clip?.hook||$('hook').value,w/2,landscape?25:square?28:h*.06,landscape?32:square?28:36,'#ffffff',w-80);
 ctx.save();ctx.translate(fx+frameW/2,fy+frameH/2);ctx.rotate(fClamp($('frameTilt').value,-12,12,-3)*Math.PI/180*((state.clips||[]).indexOf(clip)%2===1?-1:1));if($('frameShadow').checked){ctx.shadowColor='#1c22565c';ctx.shadowBlur=18;ctx.shadowOffsetY=8}const border=fClamp($('frameWidth').value,0,16,4);ctx.fillStyle=$('frameColor').value;ctx.fillRect(-frameW/2-border,-frameH/2-border,frameW+border*2,frameH+border*2);ctx.shadowBlur=0;ctx.shadowOffsetY=0;if(rec){const v=syncMedia(rec,fClamp(clip.offset,0,rec.duration-.03)+local,clip.id,t);drawVideoFrame(v,-frameW/2,-frameH/2,frameW,frameH,$('fit').value)}else demo(Math.floor(t/7),-frameW/2,-frameH/2,frameW,frameH);ctx.restore();
 const r=landscape?70:square?55:88,center=landscape?w*.78:w/2,yy=landscape?h*.55:square?h*.83:h*.85,spacing=r*1.02,left=clip?.left?clipPortraits.get(clip.id+'-left'):before,right=clip?.right?clipPortraits.get(clip.id+'-right'):partner;circlePortrait(left,center-spacing,yy,r);circlePortrait(right,center+spacing,yy,r);ctx.fillStyle='#f42b9b';ctx.beginPath();ctx.arc(center,yy,22,0,Math.PI*2);ctx.fill();ctx.save();ctx.fillStyle='#fff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='700 30px Arial';ctx.fillText($('frameConnector').value,center,yy);ctx.restore();if(landscape)text($('instruction').value,center,h*.22,25,'#394365',w*.3);
}
function framedInput(label,value,type,handler){const l=document.createElement('label'),input=document.createElement('input');l.textContent=label;input.type=type;input.value=value;if(type==='number'){input.min='0';input.step='.1'}input.onchange=()=>handler(input.value);l.append(input);return l}
async function rebuildClipPortraits(){clipPortraits.clear();for(const c of state.clips||[])for(const side of ['left','right'])if(c[side]?.src)clipPortraits.set(c.id+'-'+side,await loadImage(c[side].src))}
function refreshClipEditor(){state.clips=state.clips||[];const box=$('clipRows');box.replaceChildren();state.clips.forEach((clip,index)=>{const row=document.createElement('div');row.className='cue-card';const name=document.createElement('strong');name.textContent='Scene '+(index+1)+' · '+clip.name;row.append(name);const hint=document.createElement('p');hint.className='hint';hint.textContent=clipMedia.has(clip.id)?'Clip ready · '+Number(clip.duration).toFixed(1)+'s':'Reattach this clip';row.append(hint);const trimButton=document.createElement('button');trimButton.className='wide';trimButton.textContent='✂ Trim clip · '+Number(clip.offset||0).toFixed(2)+'s to '+Number((clip.offset||0)+clipLength(clip)).toFixed(2)+'s';trimButton.onclick=()=>openTrimEditor(clip.id);row.append(trimButton);
  const attach=document.createElement('input');attach.type='file';attach.accept='video/*';attach.onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const rec=await readClip(file);releaseMedia(clipMedia.get(clip.id));clipMedia.set(clip.id,rec);clip.name=file.name;clip.duration=rec.duration;clip.offset=0;clip.length=Math.min(clipLength(clip),rec.duration);refreshClipEditor();updateTimeline();changed()}catch(err){message(err.message)}};row.append(attach);
  row.append(framedInput('Scene heading',clip.hook||'','text',v=>{clip.hook=v.slice(0,100);changed()}));const times=document.createElement('div');times.className='row';times.append(framedInput('Trim start (seconds)',clip.offset||0,'number',v=>{clip.offset=fClamp(v,0,Math.max(0,clip.duration-.1));clip.length=Math.min(clipLength(clip),clip.duration-clip.offset);updateTimeline();refreshClipEditor();changed()}),framedInput('Scene duration (seconds)',clip.length,'number',v=>{clip.length=fClamp(v,.1,Math.min(60,clip.duration-(clip.offset||0)));refreshClipEditor();updateTimeline();changed()}));row.append(times);
  for(const side of ['left','right']){const label=document.createElement('label');label.textContent=(side==='left'?'Left':'Right')+' circular portrait'+(clip[side]?' · '+clip[side].name:' · optional');const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.onchange=async e=>{if(!e.target.files[0])return;try{clip[side]={name:e.target.files[0].name,src:await readImage(e.target.files[0])};await rebuildClipPortraits();refreshClipEditor();changed()}catch(err){message(err.message)}};label.append(input);row.append(label)}
  const buttons=document.createElement('div');buttons.className='cue-presets';for(const [label,delta] of [['↑',-1],['↓',1]]){const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-label',label==='↑'?'Move scene up':'Move scene down');b.disabled=index+delta<0||index+delta>=state.clips.length;b.onclick=()=>{const target=index+delta;[state.clips[index],state.clips[target]]=[state.clips[target],state.clips[index]];refreshClipEditor();updateTimeline();changed()};buttons.append(b)}const remove=document.createElement('button');remove.textContent='Remove clip';remove.onclick=()=>{releaseMedia(clipMedia.get(clip.id));clipMedia.delete(clip.id);state.clips.splice(index,1);refreshClipEditor();updateTimeline();changed()};buttons.append(remove);row.append(buttons);box.append(row)});if(typeof refreshCropControls==='function')refreshCropControls();$('endVideoInfo').textContent=state.endVideo?(endVideoMedia?'Ready: ':'Reattach: ')+state.endVideo.name:'';rebuildClipPortraits().then(()=>render(time)).catch(e=>message(e.message));}
$('clipUpload').onchange=async e=>{try{for(const file of e.target.files){if(state.clips.length>=6){message('Maximum 6 clips per project.');break}const rec=await readClip(file),id=clipId();clipMedia.set(id,rec);state.clips.push({id,name:file.name,duration:rec.duration,offset:0,length:Math.min(7,rec.duration),hook:'',left:null,right:null})}state.template='framed';buildTemplates();refreshClipEditor();updateTimeline();time=0;changed();message('Clips ready. Set scene timings and portrait inputs in step 3.')}catch(err){message(err.message)}finally{e.target.value=''}};
$('endVideoUpload').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const rec=await readClip(file);releaseMedia(endVideoMedia);endVideoMedia=rec;state.endVideo={name:file.name,duration:rec.duration};refreshClipEditor();changed()}catch(err){message(err.message)}};
$('clearEndVideo').onclick=()=>{releaseMedia(endVideoMedia);endVideoMedia=null;state.endVideo=null;$('endVideoUpload').value='';refreshClipEditor();changed()};
let trimClipId=null,trimRangePlaying=false;
function trimValidation(start,end,total){if(!Number.isFinite(start)||!Number.isFinite(end))return 'Enter a valid start and end time.';if(start<0||end>total+.001)return 'Keep the range inside the source video.';if(end-start<.1)return 'Select at least 0.10 seconds.';if(end-start>60.001)return 'Select up to 60 seconds per scene.';return ''}
function trimStatus(){const record=clipMedia.get(trimClipId);if(!record)return false;const start=Number($('trimIn').value),end=Number($('trimOut').value),error=trimValidation(start,end,record.duration);$('trimInfo').textContent=error||'Selected: '+start.toFixed(2)+'s → '+end.toFixed(2)+'s · '+(end-start).toFixed(2)+' seconds';$('trimApply').disabled=!!error;$('trimPlay').disabled=!!error;return !error}
function openTrimEditor(id){if(exporting)return;const record=clipMedia.get(id),clip=state.clips.find(c=>c.id===id);if(!record||!clip){message('Reattach this clip before trimming.');return}playing=false;$('play').textContent='▶';if(typeof stopAudioMix==='function')stopAudioMix();stopFramedPlayback();trimClipId=id;trimRangePlaying=false;const player=$('trimPreview');player.src=record.url;$('trimIn').value=Number(clip.offset||0).toFixed(2);$('trimOut').value=(Math.floor(Math.min(record.duration,Number(clip.offset||0)+clipLength(clip))*100)/100).toFixed(2);$('trimIn').max=$('trimOut').max=record.duration;player.onloadedmetadata=()=>{player.currentTime=Number($('trimIn').value)};$('trimTitle').textContent='Trim · '+clip.name;trimStatus();$('trimDialog').showModal();}
$('trimPreview').ontimeupdate=()=>{const player=$('trimPreview');$('trimClock').textContent='Source position: '+player.currentTime.toFixed(2)+'s';if(trimRangePlaying&&player.currentTime>=Number($('trimOut').value)){player.pause();trimRangePlaying=false;player.currentTime=Number($('trimOut').value)}};
$('trimMarkIn').onclick=()=>{$('trimIn').value=$('trimPreview').currentTime.toFixed(2);trimRangePlaying=false;trimStatus()};
$('trimMarkOut').onclick=()=>{$('trimOut').value=$('trimPreview').currentTime.toFixed(2);trimRangePlaying=false;trimStatus()};
for(const id of ['trimIn','trimOut'])$(id).oninput=()=>{trimRangePlaying=false;$('trimPreview').pause();trimStatus()};
$('trimPlay').onclick=()=>{if(!trimStatus())return;const player=$('trimPreview');player.currentTime=Number($('trimIn').value);trimRangePlaying=true;player.play().catch(e=>{$('trimInfo').textContent='Preview could not play: '+e.message;trimRangePlaying=false})};
$('trimReset').onclick=()=>{const record=clipMedia.get(trimClipId);if(!record)return;$('trimIn').value='0.00';$('trimOut').value=(Math.floor(Math.min(60,record.duration)*100)/100).toFixed(2);trimRangePlaying=false;$('trimPreview').pause();$('trimPreview').currentTime=0;trimStatus()};
$('trimApply').onclick=()=>{if(!trimStatus())return;const clip=state.clips.find(c=>c.id===trimClipId);if(!clip)return;clip.offset=Number($('trimIn').value);clip.length=Number($('trimOut').value)-clip.offset;const start=state.clips.slice(0,state.clips.indexOf(clip)).reduce((sum,c)=>sum+clipLength(c),0);$('trimDialog').close();time=start;refreshClipEditor();updateTimeline();changed();message('Trim applied. Scene uses '+clip.length.toFixed(2)+' seconds; original file unchanged.');};
$('trimClose').onclick=()=>$('trimDialog').close();
$('trimDialog').addEventListener('close',()=>{trimRangePlaying=false;const player=$('trimPreview');player.pause();player.removeAttribute('src');player.load();trimClipId=null});
